(()=>{'use strict';const KEY='toolbox-appearance';function pref(){try{return localStorage.getItem(KEY)||'system'}catch(e){return 'system'}}function render(){const view=document.getElementById('view');if(!view)return;const account=view.querySelector('.account-page');const existing=view.querySelector('#toolboxAppearance');if(!account){if(existing)existing.remove();return}if(existing)return;const section=document.createElement('section');section.id='toolboxAppearance';section.className='toolbox-appearance';section.setAttribute('aria-label','Appearance settings');section.innerHTML='<h2>Appearance</h2><p>Choose how Toolbox looks on this device.</p><div class="appearance-options">'+[['system','Automatic','Follow your phone settings'],['light','Light','Always use light appearance'],['dark','Dark','Always use dark appearance']].map(([v,t,d])=>'<label><input type="radio" name="toolboxAppearance" value="'+v+'" '+(pref()===v?'checked':'')+'><span><strong>'+t+'</strong><small>'+d+'</small></span></label>').join('')+'</div><div class="appearance-security"><strong>Your documents stay under your control.</strong> Local records remain on this device unless you export or share them. Cloud sync and end-to-end encryption are not active in this test build. Do not assume uploaded documents are inaccessible to all parties until cloud security has been implemented and independently tested.</div>';account.appendChild(section);section.addEventListener('change',e=>{if(e.target.name!=='toolboxAppearance')return;const val=e.target.value;if(!['system','light','dark'].includes(val))return;try{localStorage.setItem(KEY,val)}catch(err){}document.documentElement.dataset.toolboxTheme=val})}let scheduled=false;const observer=new MutationObserver(()=>{if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;render()})});function start(){const view=document.getElementById('view');if(!view)return;observer.observe(view,{childList:true,subtree:false});render()}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start);else start()})();
